if (IWnotchecked && (synackecn == 1)) {
   losscount++;
   IWnotchecked = 0; # 二度とチェックしない
}

if (Retransmitting && IWnotchecked && ((seqno - ISN) < IW))) {
   losscount++;
   IWnotchecked = 0; # この"if"全体を二度と実行しない
} else {
   IWnotchecked = 0; # IWを超えたのでチェックをやめる
}

if (conncount > 1000) {
   if (losscount/conncount > threshold) {
      # エラーのあるコネクションの数が多すぎる
      IW = IW * MulDecr;
   } else {
      IW = IW + AddIncr;
   }
}
